function p3WKey(aid,k){return 'p3w:'+aid+':'+k}
function p3WLast(id){try{return JSON.parse(localStorage.getItem('p3wlast')||'{}')[id]||null}catch(e){return null}}
function p3WSetLast(id,v){try{const o=JSON.parse(localStorage.getItem('p3wlast')||'{}');o[id]=v;localStorage.setItem('p3wlast',JSON.stringify(o))}catch(e){}}
