function p3WRestTick(){clearInterval(P3REST.t);P3REST.t=setInterval(()=>{const el=document.getElementById('p3wRestT');const left=Math.max(0,Math.round((P3REST.end-Date.now())/1000));if(!el||left<=0){clearInterval(P3REST.t);if(left<=0&&P3W.on){try{navigator.vibrate&&navigator.vibrate(200)}catch(e){}p3WDraw()}return}el.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`},500)}
