runVoice=(function(old){return async function(){const t=$('#v-text');const text=(t&&t.value||'');const meal=p3ShownMeal();
  P3VM={meal,at:p3AtFor(meal),force:P3MP,words:/\b(breakfast|lunch|dinner|tea|supper|snack)\b/i.test(text)};
  try{return await old.apply(this,arguments)}finally{P3VM=null;P3MP=false}}})(runVoice);
parseFoodPhoto=(function(old){return async function(){const meal=p3ShownMeal();P3VM={meal,at:p3AtFor(meal),force:true};try{return await old.apply(this,arguments)}finally{P3VM=null;P3MP=false}}})(parseFoodPhoto);
// ================= P3: Ask Koach (type or talk a question; answers use your own numbers) =================
let P3ASK={busy:false,q:''};
function p3AskHist(){try{return JSON.parse(localStorage.getItem('p3ask_'+(UID||''))||'[]')}catch(e){return []}}
function p3AskSave(h){try{localStorage.setItem('p3ask_'+(UID||''),JSON.stringify(h.slice(-12)))}catch(e){}}
function p3AskCtx(){const t0=todayDate(),k=iso(t0);const dt=dayTypeFor(k);const d=D()[k]||{};const tt=foodTotals(d);const L7=[];
  for(let i=1;i<=7;i++){const dd=D()[iso(addD(t0,-i))];if(dd&&(dd.food||[]).length)L7.push(foodTotals(dd))}
  const line=x=>{const tg=x.macro?nutTarget(x.k,dt):{lo:x.lo,hi:x.hi};const v=Math.round(tt[x.k]||0);const av=L7.length?Math.round(L7.reduce((a,t)=>a+(+t[x.k]||0),0)/L7.length):null;
    return `${x.l}: today ${v}${x.u}${tg&&tg.lo!=null?`, target ${tg.lo}${tg.hi?'-'+tg.hi:'+'}${x.u}`:''}${tg&&tg.hi&&v>tg.hi?' (OVER)':''}${av!=null?`, 7-day avg ${av}${x.u}`:''}`};
  const sl=[1,2,3].map(i=>{const dd=D()[iso(addD(t0,-i+1))];const h=sleepHours(dd);return h!=null?h+'h':null}).filter(Boolean);
  let su=[];try{su=suppItems(d).map(s=>s.name)}catch(e){}
  const pl=planFor(t0);const foods=(d.food||[]).map(i=>`${i.meal} ${i.at||''}: ${i.name}${i.qty?' ('+i.qty+')':''}`).join('; ');
  return `About them: ${typeof ABOUT!=='undefined'?ABOUT:''}. Eating approach: ${typeof APPROACH!=='undefined'?APPROACH:''}. Today is ${fmtD(t0,{weekday:'long',day:'numeric',month:'long'})}, a ${dt} day${pl&&!pl.pre?`, plan: ${TNAME[pl.type]}${planSkipped(k)?` but they chose not to do it${(d.extras||[]).length?` and did their own session instead (${d.extras.map(x=>`${x.desc||x.kind}${x.dur?` ${x.dur} min`:''}`).join('; ')}), the only session today`:''}`:(d.extras||[]).length?`, plus extra: ${d.extras.map(x=>`${x.desc||x.kind}${x.dur?` ${x.dur} min`:''}`).join('; ')}`:''}, week ${pl.wk} of 16`:''}.
Food today: ${foods||'nothing logged yet'}.
Supplements taken today: ${su.join(', ')||'none'}.
Nutrients (today vs target, with 7-day average over ${L7.length} logged days):
${NUTS.map(line).join('\n')}
Sleep last nights: ${sl.join(', ')||'not logged'}.
Days over the safe upper limit (last 14 logged days): ${(()=>{try{return Object.keys(P3UL).map(k=>{const r=p3ULfreq(k);return r.o14?`${k} ${r.o14}/${r.n14}`:''}).filter(Boolean).join(', ')||'none'}catch(e){return 'unknown'}})()}.`}
function p3AskHTML(){const h=p3AskHist();
  return `<div class="p3ask"><div class="p3askin"><textarea id="p3askT" rows="2" placeholder="Ask anything, e.g. I'm over on some vitamins, is that a risk?">${esc(P3ASK.q||'')}</textarea></div>
  <div class="p3askb">${typeof speakBtn==='function'?speakBtn('p3askT'):''}<button type="button" class="primary" id="p3askGo" ${P3ASK.busy?'disabled':''}>${P3ASK.busy?'Thinking…':'Ask'}</button></div>
  <div class="p3askl">${h.slice().reverse().map(x=>`<div class="p3qa"><b>${esc(x.q)}</b><p>${esc(x.a).replace(/\n/g,'<br>')}</p><small>${esc(x.at||'')}</small></div>`).join('')}</div>
  ${h.length?`<button type="button" class="linkbtn" id="p3askClr">Clear these</button>`:''}</div>`}
function p3AskOpen(q){if(q!=null)P3ASK.q=q;p1Sheet(`<div class="kshead"><div><h2>Ask Koach</h2><small class="ds">Answers use your logged food, sleep and plan</small></div><button type="button" class="x" id="p1X" aria-label="Close">${ico('x')}</button></div><div id="p3askHost">${p3AskHTML()}</div>`);setTimeout(()=>{const t=$('#p3askT');if(t&&!q)t.focus()},80)}
function p3AskDraw(){const h=$('#p3askHost');if(h)h.innerHTML=p3AskHTML()}
async function p3AskGo(){const t=$('#p3askT');const q=(t&&t.value||'').trim();if(!q){toast('Type or say your question first');return}try{stopListen()}catch(e){}
  P3ASK={busy:true,q};p3AskDraw();const hist=p3AskHist().slice(-4).map(x=>`Q: ${x.q}\nA: ${x.a}`).join('\n\n');
  try{const out=await sample.json(`You are Koach, a friendly, plain-spoken coach in a training and food app. Answer ${userName()||'the user'}'s question using their own numbers below. Speak to them directly by first name now and then.
How to answer, like a good coach who has looked at their numbers:
1. Start with a one-line verdict (e.g. "You're over on zinc and magnesium, and it's your supplements doing it.").
2. Then a clear recommendation they can act on today, naming the actual supplement and amounts: drop it, take it every other day, halve it, or keep it. Show the sum: "Vitals Plus gives you 15 mg zinc, food gives about 12 mg, so you're at 27 against a 25 mg safe limit. Drop to every second day and you average 19 mg."
3. Say what changing it would leave them short on, using their food averages, and the 1-2 foods that would cover it.
4. Judge how steady the data is: if fewer than 5 days are logged, or the food numbers swing a lot day to day, say so and give the call anyway with how long to keep watching (e.g. "log another week before changing, but lean towards dropping it").
4b. When a supplement with lots of things in it is the cause (a multivitamin like Vitals Plus), go through what else it gives them. Using their food averages, name which nutrients would drop below target if they stopped it, by how much, and which would still be fine. Then make the call: drop it, every second day, or swap to a single-nutrient product for the one they actually need.
5. Separate what matters (vitamin A as retinol, vitamin D, iron, zinc, selenium, iodine, magnesium and folic acid from supplements) from what doesn't (vitamin C, B12, potassium and most things from food).
Be direct and specific. Do not tell them to "look at it" or "talk to your GP" as a way of not answering. Only mention a GP or pharmacist for real warning signs, a medicine they take, or a diagnosed condition, and still give your view. Never diagnose. If a supplement's contents are only estimated, say so in one short phrase and suggest snapping the label in Food > Supplements > What's in them.
Plain words, no jargon; under 170 words unless they ask for more.
${p3AskCtx()}
${hist?'Earlier in this chat:\n'+hist+'\n':''}Question: ${q}
Reply as JSON: {"answer":"..."}`,{maxTokens:2500});
    const a=String(out&&out.answer||'').trim()||'Sorry, I could not answer that. Try asking another way.';const h=p3AskHist();const n=new Date();h.push({q,a,at:fmtD(n,{day:'numeric',month:'short'})+' '+fmtT(n.getHours()*60+n.getMinutes())});p3AskSave(h);P3ASK={busy:false,q:''}}
  catch(e){P3ASK={busy:false,q};toast(foodErr(e),5000)}p3AskDraw()}
document.addEventListener('click',e=>{const c=q=>e.target.closest&&e.target.closest(q);let x;
  if(x=c('[data-p3ask]')){e.preventDefault();e.stopImmediatePropagation();p3AskOpen(x.dataset.p3ask||null);return}
  if(c('#p3askGo')){p3AskGo();return}
  if(c('#p3askClr')){p3AskSave([]);p3AskDraw()}},true);
document.addEventListener('input',e=>{if(e.target.id==='p3askT')P3ASK.q=e.target.value});
p3Koach=(function(old){return function(k){const bar=`<button type="button" class="p3askbar" data-p3ask="">${ico('sparkles')}<span class="p3askt">Ask Koach anything</span>${MIC}</button>`;const h=old(k);return /<\/div>$/.test(h)?h.replace(/<\/div>$/,bar+'</div>'):h+bar}})(p3Koach);
microsHTML=(function(old){return function(t,dt,k){const h=old(t,dt,k);if(!h||!t||!t.n)return h;return h.replace(/<\/details>\s*$/,`<button type="button" class="linkbtn p3askv" data-p3ask="Am I over on any vitamins or minerals, and is there any risk from that?">Ask Koach about these ›</button></details>`)}})(microsHTML);
// ================= P3: a nutrient's sheet shows where today's came from, and what to eat when short =================
function p3SrcHTML(k){const n=NUTS.find(x=>x.k===k);if(!n)return '';const dk=iso(sel);const d=D()[dk]||{};const tg=nutTarget(k,dayTypeFor(dk))||{};
  const rows=[];(d.food||[]).forEach(i=>{const v=k==='kcal'?kcalOf(i):(+i[k]||0);if(v>0)rows.push({name:i.name,v,meal:i.meal})});let su=[];try{su=suppItems(d)}catch(e){}su.forEach(i=>{const v=+i[k]||0;if(v>0)rows.push({name:i.name,v,sup:1})});
  const tot=rows.reduce((a,r)=>a+r.v,0);rows.sort((a,b)=>b.v-a.v);const f=v=>v>=10?Math.round(v):Math.round(v*10)/10;
  const top=rows.slice(0,5),rest=rows.slice(5).reduce((a,r)=>a+r.v,0);const u=n.u==='kcal'?' kcal':' '+n.u;
  const row=(nm,v,tag)=>`<div class="p3srcR"><span>${esc(nm)}${tag?` <i>${tag}</i>`:''}</span><b>${f(v)}${u}</b><em style="width:${Math.max(4,Math.round(v/tot*100))}%"></em></div>`;
  return `<section class="p1blk p3srcS"><h3>Where today's came from</h3>${rows.length?top.map(r=>row(r.name,r.v,r.sup?'supplement':r.meal)).join('')+(rest>0?row('Everything else',rest):''):`<p class="ds" style="margin:0">No ${esc(n.l)} logged today.</p>`}</section>`}
p1NutInfo=(function(old){return function(k){old(k);const host=document.querySelector('#p1Host .p1sheet');if(!host)return;const n=NUTS.find(x=>x.k===k);const dk=iso(sel);const t=foodTotals(D()[dk]||{});const tg=nutTarget(k,dayTypeFor(dk))||{};
  const head=host.querySelector('.kshead');if(head)head.insertAdjacentHTML('afterend',p3SrcHTML(k));
  const v=t[k]||0;const f=x=>x>=10?Math.round(x):Math.round(x*10)/10;
  host.querySelectorAll('.p1blk h3').forEach(h=>{if(h.textContent==='Foods that have it'){h.textContent=tg.lo&&v<tg.lo?`Short by ${f(tg.lo-v)} ${n.u}. Top up with`:tg.hi&&v>tg.hi&&!tg.lo?'Over today. It mostly comes from':'Where else to get it';const s=h.parentElement;const w=host.querySelector('.p3srcS');if(w&&s!==w.nextElementSibling)w.insertAdjacentElement('afterend',s)}})}})(p1NutInfo);
// ================= P3: safe upper limits: a note when too much of something could be a risk =================
const P3UL={vitA:{ul:3000,risk:'Too much vitamin A over time can harm the liver and bones. The limit is for retinol (liver, fish oils, supplements); vitamin A from carrots and other veg is not a worry.'},
 vitD:{ul:100,risk:'Very high vitamin D over weeks can raise calcium in the blood. This nearly always comes from high-dose supplements, not food.'},
 vitC:{ul:2000,risk:'Above this, vitamin C can upset your stomach. Your body passes out what it doesn’t need, so it’s not a lasting risk.'},
 iron:{ul:45,risk:'Too much iron can cause stomach upset and, taken high for long, build up in the body. Don’t take an iron supplement unless a GP has told you to.'},
 zinc:{ul:25,risk:'Too much zinc over time blocks copper and can cause stomach upset. Usually from supplements stacked on top of meat and shellfish.'},
 selenium:{ul:255,risk:'Too much selenium over time can cause hair and nail problems. Brazil nuts are very high: 1 or 2 a day is plenty.'},
 iodine:{ul:600,risk:'Too much iodine over time can upset the thyroid. Usually from seaweed or kelp supplements.'},
 calcium:{ul:2500,risk:'Too much calcium, mostly from supplements, can raise the risk of kidney stones.'},
 choline:{ul:3500,risk:'Very high choline can cause a fishy body smell and low blood pressure.'},
 omega3:{ul:5,risk:'Above about 5 g a day of fish oil can thin the blood. Food alone won’t get you there.'},
 magnesium:{ul:250,supp:1,risk:'From supplements, more than 250 mg a day can cause loose stools. Magnesium from food has no limit.'},
 folate:{ul:1000,supp:1,risk:'More than 1000 µg a day of folic acid from supplements or fortified foods can hide a B12 shortage.'}};
function p3ULadvice(k,d){let sp=[];try{sp=suppItems(d).filter(i=>+i[k]>0)}catch(e){}if(!sp.length)return ' It\u2019s coming from food today, so no change needed unless it happens most days.';const u=P3UL[k],n=NUTS.find(x=>x.k===k);const tot=foodTotals(d)[k]||0,s=sp.reduce((a,i)=>a+(+i[k]||0),0),fo=tot-s;const f=x=>x>=10?Math.round(x):Math.round(x*10)/10;const big=sp.sort((a,b)=>b[k]-a[k])[0];
  const lim=u.supp?s:tot;const without=u.supp?s-(+big[k]):tot-(+big[k]);return ` <b>${esc(big.name)} gives ${f(+big[k])} ${n.u}</b>${u.supp?'':`, food ${f(fo)} ${n.u}`}. Without it you'd be at ${f(without)} ${n.u}${without<=u.ul?', under the limit':''}. If this keeps happening, drop it or take it every second day.`}
function p3ULval(k,d){const u=P3UL[k];if(!u)return null;if(!u.supp)return foodTotals(d)[k]||0;let s=0;try{suppItems(d).forEach(i=>s+=(+i[k]||0))}catch(e){}return s}
p1NutInfo=(function(old){return function(k){old(k);const u=P3UL[k];const n=NUTS.find(x=>x.k===k);const host=document.querySelector('#p1Host .p1sheet');if(!host||!n)return;const d=D()[iso(sel)]||{};
  const v=p3ULval(k,d),tot=foodTotals(d)[k]||0,tg=nutTarget(k,dayTypeFor(iso(sel)))||{};const f=x=>x>=10?Math.round(x):Math.round(x*10)/10;let h='';
  if(!u){if(tg.lo&&tot>tg.lo*1.5&&!tg.hi)h=`<section class="p1blk p3ul ok"><h3>Is too much a risk?</h3><p style="margin:0">No safe upper limit has been set for ${esc(n.l)}, because no harm has been seen from high amounts in food. Being over target is fine.</p></section>`}
  else if(v>u.ul)h=`<section class="p1blk p3ul hi"><h3>Above the safe limit</h3><p style="margin:0"><b>${f(v)} ${n.u}${u.supp?' from supplements':''}</b> today, over the ${u.ul} ${n.u} a day that's safe long term. ${esc(u.risk)} One day over isn't a worry.${p3ULadvice(k,d)}</p></section>`;
  else if(v>u.ul*0.8)h=`<section class="p1blk p3ul mid"><h3>Close to the safe limit</h3><p style="margin:0">${f(v)} ${n.u}${u.supp?' from supplements':''} today, near the ${u.ul} ${n.u} safe daily limit. ${esc(u.risk)}</p></section>`;
  else if(tg.lo&&tot>tg.lo)h=`<section class="p1blk p3ul ok"><h3>Is too much a risk?</h3><p style="margin:0">No. You're over target but well under the safe limit of ${u.ul} ${n.u} a day${u.supp?' from supplements':''}.</p></section>`;
  if(!h)return;const a=host.querySelector('.p3srcS')||host.querySelector('.kshead');a.insertAdjacentHTML('afterend',h)}})(p1NutInfo);
var P3NBW=1;// weekly view: compare the daily average with the safe limit
nutBar=(function(old){return function(n,val,tg){const h=old(n,val,tg);const u=P3UL[n.k];if(!u||u.supp||!(val/P3NBW>u.ul))return h;return h.replace(`<span>${n.l} <i`,`<span>${n.l} <span class="p3ulb">Over safe limit</span> <i`)}})(nutBar);
// ================= P3: Koach watches how often you go over a safe limit =================
function p3ULfreq(k){const t0=todayDate();let n7=0,o7=0,n14=0,o14=0;for(let i=0;i<14;i++){const d=D()[iso(addD(t0,-i))];if(!d||!((d.food||[]).length||(()=>{try{return suppItems(d).length}catch(e){return 0}})()))continue;const over=p3ULval(k,d)>P3UL[k].ul;n14++;if(over)o14++;if(i<7){n7++;if(over)o7++}}return {n7,o7,n14,o14}}
function p3ULrisks(){return Object.keys(P3UL).map(k=>({k,...p3ULfreq(k)})).filter(r=>r.o7>=3||r.o14>=5).sort((a,b)=>b.o14-a.o14)}
p3Koach=(function(old){return function(k){const h=old(k);let rs=[];try{rs=p3ULrisks().slice(0,2)}catch(e){}if(!rs.length)return h;
  const al='<div class="p3ulrow">'+rs.map(r=>{const n=NUTS.find(x=>x.k===r.k);return `<button type="button" class="p3ulchip" data-nutinfo="${r.k}" data-p3ul14="1"><span class="p3ulic">!</span>${esc(n.l)} high · ${r.o7>=3?`${r.o7}/${r.n7}`:`${r.o14}/${r.n14}`} days</button>`}).join('')+'</div>';
  const chips=al.replace('<div class="p3ulrow">','').replace(/<\/div>$/,'');
  if(h.includes('<div class="p3chips">'))return h.replace('<div class="p3chips">','<div class="p3chips">'+chips);
  return h.includes('class="p3askbar"')?h.replace('<button type="button" class="p3askbar"',al+'<button type="button" class="p3askbar"'):h+al}})(p3Koach);
p1NutInfo=(function(old){return function(k){old(k);if(!P3UL[k])return;const host=document.querySelector('#p1Host .p1sheet');if(!host)return;const r=p3ULfreq(k);if(!r.n14)return;
  const msg=r.o14===0?`Under the safe limit every day you've logged in the last 2 weeks.`:(r.o7>=3||r.o14>=5)?`Over the safe limit on <b>${r.o14} of the last ${r.n14} days</b> you logged. That's often enough to be worth acting on. See what's behind it below.`:`Over the safe limit on ${r.o14} of the last ${r.n14} days you logged. Now and then is fine. Koach will flag it on Today if it becomes a habit.`;
  const s=host.querySelector('.p3ul');const blk=`<p class="p3ulf">${msg}</p>`;if(s)s.insertAdjacentHTML('beforeend',blk);else{const a=host.querySelector('.p3srcS')||host.querySelector('.kshead');a.insertAdjacentHTML('afterend',`<section class="p1blk p3ul ${r.o14?'mid':'ok'}"><h3>Last 2 weeks</h3>${blk}</section>`)}}})(p1NutInfo);
// ================= P3: see and fix exactly what's in each supplement; Koach gives a straight answer =================
const P3SK=()=>MICRO.filter(x=>x!=='caffeine');
function p3NU(k){const n=NUTS.find(x=>x.k===k);return n?n.u:''}
function p3NL(k){const n=NUTS.find(x=>x.k===k);return n?n.l:k}
function p3SuppCard(s){const ks=P3SK().filter(k=>+((s.nut||{})[k])>0);const rest=P3SK().filter(k=>!ks.includes(k));
  return `<section class="p1blk p3sc" data-sid="${esc(String(s.id))}"><div class="p3sch"><div><b>${esc(s.name)}</b><small>${s.src==='label'?'From the label':s.src==='you'?'Entered by you':'Estimated from the name. Add a photo or screenshot of the label to make it exact.'}</small></div></div>
  <div class="field"><label class="label">Daily dose</label><input type="text" value="${esc(s.dose||'')}" data-p3sd="${esc(String(s.id))}" placeholder="e.g. 2 tablets"></div>
  <div class="p3sg">${ks.map(k=>`<label class="p3sn"><span>${esc(p3NL(k))}</span><input type="number" inputmode="decimal" min="0" step="any" value="${+s.nut[k]}" data-p3sn="${esc(String(s.id))}|${k}"><i>${p3NU(k)}</i></label>`).join('')||'<p class="ds" style="margin:0">No vitamins or minerals listed.</p>'}</div>
  <div class="p3sa"><select data-p3sadd="${esc(String(s.id))}"><option value="">+ Add a nutrient</option>${rest.map(k=>`<option value="${k}">${esc(p3NL(k))}</option>`).join('')}</select>
  <label class="linkbtn p3slab">Read the label (photo or screenshot)<input type="file" accept="image/*" data-p3slab="${esc(String(s.id))}" hidden></label>
  <button type="button" class="linkbtn" data-p3srm="${esc(String(s.id))}">Remove</button></div></section>`}
function p3SuppOpen(){const l=supps();p1Sheet(`<div class="kshead"><div><h2>What's in your supplements</h2><small class="ds">Per daily dose. Changes save as you type.</small></div><button type="button" class="x" id="p1X" aria-label="Close">${ico('x')}</button></div><div id="p3sHost">${l.length?l.map(p3SuppCard).join(''):'<p class="ds">No supplements added yet.</p>'}</div>`)}
async function p3SuppSave(fn,redraw){const l=clone(supps());fn(l);await persistMeta('supps',{list:l});if(redraw){const h=$('#p3sHost');if(h)h.innerHTML=l.map(p3SuppCard).join('')}}
document.addEventListener('click',e=>{const c=q=>e.target.closest&&e.target.closest(q);let x;
  if(c('[data-p3sopen]')){e.preventDefault();p3SuppOpen();return}
  if(x=c('[data-p3srm]')){const id=x.dataset.p3srm;const s=supps().find(z=>String(z.id)===id);if(!s)return;if(x.dataset.sure!=='1'){x.dataset.sure='1';x.textContent='Tap again to remove';return}p3SuppSave(l=>{const i=l.findIndex(z=>String(z.id)===id);if(i>=0)l.splice(i,1)},true).then(()=>toast(`Removed ${s.name}`))}});
