  if(!f.pl||f.pl.pre)return `<div class="p3peek">${head}<b class="p3pkt">No plan for this day</b>${f.ex.length?`<ul class="p3pkx">${f.ex.map(x=>`<li>${esc(x.desc||x.kind)}</li>`).join('')}</ul>`:''}${open}</div>`;
